sealed interface GuestLog : LogCategory {

    class Loaded internal constructor(version: String) : GuestLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "guest")
            put("event_name", "loaded")
            put("version", version)
        }
    }

    companion object {
        // guest をロードしたときのログ
        fun loaded(version: String) = Loaded(version)
    }
}
